        }

        .milestone-arrow {
            font-size: var(--body-size);
            color: rgba(255,255,255,0.5);
        }

        .measles-milestones {
            display: grid;
            grid-template-columns: 1fr 1fr 1fr;
            gap: clamp(0.4rem, 1vw, 1rem);
            padding: 0 var(--slide-padding) clamp(0.5rem, 1.5vw, 1.5rem);
        }

        .milestone-card {
            background: rgba(255,255,255,0.05);
            border-left: 3px solid var(--accent);
            padding: clamp(0.4rem, 0.8vw, 0.8rem) clamp(0.6rem, 1.2vw, 1.2rem);
            border-radius: 0 4px 4px 0;
        }

        .milestone-year {
            font-family: var(--font-display);
            font-size: var(--h3-size);
            color: var(--accent-light);
        }

        .milestone-desc {
            font-family: var(--font-body);
            font-size: var(--small-size);
            color: rgba(255,255,255,0.65);
            margin-top: 2px;
            line-height: 1.4;
        }

        /* ===========================================
           SLIDE 5: SMALLPOX ERADICATION
           White background, timeline visualization
           =========================================== */
        .slide-smallpox { background: var(--bg-primary); }

        .smallpox-layout {
            display: grid;
            grid-template-rows: auto auto 1fr auto;
            height: 100%;
            overflow: hidden;
        }

        .eradication-timeline {
            display: flex;
            flex-direction: column;
            justify-content: center;
            padding: 0 var(--slide-padding);
            gap: clamp(0.2rem, 0.5vh, 0.6rem);
            overflow: hidden;
        }

        .timeline-spine {
            display: flex;
            flex-direction: column;
            gap: 0;
        }

        .timeline-event {
            display: grid;
            grid-template-columns: clamp(40px, 6vw, 72px) 20px 1fr;
            align-items: center;
            gap: clamp(0.4rem, 0.8vw, 0.8rem);
            position: relative;
        }

        .t-year {
            font-family: var(--font-display);
            font-size: clamp(0.75rem, 1.6vw, 1.1rem);
            color: var(--accent);
            text-align: right;
        }

        .t-node {
            display: flex;
            flex-direction: column;
            align-items: center;
            height: 100%;
        }

        .t-dot {
            width: clamp(8px, 1.2vw, 14px);
            height: clamp(8px, 1.2vw, 14px);
            border-radius: 50%;
            background: var(--accent);
            flex-shrink: 0;
            z-index: 1;
        }

        .t-dot.major {
            background: var(--text-primary);
            border: 3px solid var(--accent);
        }

        .t-line {
            flex: 1;
            width: 2px;
            background: var(--border);
            min-height: clamp(12px, 2.5vh, 28px);
        }

        .t-text {
            font-family: var(--font-body);
            font-size: var(--small-size);
            color: var(--text-secondary);
            line-height: 1.4;
            padding: clamp(0.2rem, 0.4vh, 0.4rem) 0;
        }

        .t-text strong {
            color: var(--text-primary);
            display: block;
            font-size: var(--body-size);
        }

        .smallpox-factors {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: clamp(0.4rem, 1vw, 1rem);
            padding: 0 var(--slide-padding) clamp(0.5rem, 1.5vw, 1.5rem);
        }

        .factor-chip {
            background: var(--accent-pale);
            border: 1px solid rgba(204, 34, 0, 0.2);
            border-radius: 4px;
            padding: clamp(0.3rem, 0.7vw, 0.7rem) clamp(0.5rem, 1vw, 1rem);
            font-family: var(--font-body);
            font-size: var(--small-size);
            color: var(--text-primary);
            line-height: 1.4;
        }

        .factor-chip strong {
            color: var(--accent);
            display: block;
            font-size: var(--label-size);
            text-transform: uppercase;
            letter-spacing: 0.08em;
            margin-bottom: 2px;
        }

        /* ===========================================
           SLIDE 6: HERD IMMUNITY MECHANISM
           Dark background, diagram illustration
           =========================================== */
        .slide-herd { background: #0a0a0a; }

        .herd-layout {
            display: grid;
            grid-template-rows: auto auto 1fr;
            height: 100%;
            overflow: hidden;
        }

        .herd-diagram {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: clamp(1rem, 3vw, 3rem);
            padding: 0 var(--slide-padding) clamp(0.5rem, 1.5vw, 1.5rem);
            align-items: center;
            flex: 1;
            overflow: hidden;
        }

        .herd-panel {
            display: flex;
            flex-direction: column;
            gap: clamp(0.5rem, 1.2vw, 1.2rem);
        }

        .herd-panel-title {
            font-family: var(--font-display);
            font-size: var(--h3-size);
            color: rgba(255,255,255,0.55);
            border-bottom: 1px solid rgba(255,255,255,0.1);
            padding-bottom: clamp(0.3rem, 0.6vw, 0.6rem);
        }

        .herd-panel-title.active-title { color: var(--text-light); }

        /* Population grid of people icons */
        .population-grid {
            display: grid;
            grid-template-columns: repeat(7, 1fr);
            gap: clamp(3px, 0.5vw, 8px);
        }

        .person-icon {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 2px;
        }

        .person-head {
            width: clamp(10px, 1.8vw, 22px);
            height: clamp(10px, 1.8vw, 22px);
            border-radius: 50%;
        }

        .person-body {
            width: clamp(8px, 1.4vw, 18px);
            height: clamp(12px, 2.2vw, 28px);
            border-radius: 4px 4px 6px 6px;
        }

        /* Person state colors */
        .p-vaccinated .person-head { background: #4ade80; }
        .p-vaccinated .person-body { background: #16a34a; }
        .p-unvaccinated .person-head { background: #fbbf24; }
        .p-unvaccinated .person-body { background: #d97706; }
        .p-vulnerable .person-head { background: #60a5fa; }
        .p-vulnerable .person-body { background: #2563eb; }
        .p-infected .person-head { background: #f87171; }
        .p-infected .person-body { background: #dc2626; }
        .p-protected .person-head { background: #60a5fa; box-shadow: 0 0 6px rgba(96,165,250,0.6); }
        .p-protected .person-body { background: #2563eb; box-shadow: 0 0 6px rgba(37,99,235,0.6); }

        .herd-legend {
            display: flex;
            flex-wrap: wrap;
            gap: clamp(0.3rem, 0.8vw, 0.8rem);
            padding: 0 var(--slide-padding) clamp(0.5rem, 1.5vw, 1.5rem);
        }

        .legend-person {
            display: flex;
            align-items: center;
            gap: 6px;
            font-family: var(--font-body);
            font-size: var(--small-size);
            color: rgba(255,255,255,0.6);
        }

        .legend-swatch {
            width: clamp(10px, 1.5vw, 16px);
            height: clamp(10px, 1.5vw, 16px);
            border-radius: 3px;
        }

        /* ===========================================
           SLIDE 7: REMAINING CHALLENGES
           White background, partial data visualization
           =========================================== */
        .slide-challenges { background: var(--bg-secondary); }

        .challenges-layout {
            display: grid;
            grid-template-rows: auto auto 1fr auto;
            height: 100%;
            overflow: hidden;
        }

        .challenge-bars {
            display: flex;
            flex-direction: column;
            justify-content: center;
            gap: clamp(0.5rem, 1.2vh, 1.2rem);
            padding: 0 var(--slide-padding);
            overflow: hidden;
        }

        .challenge-row {
            display: grid;
            grid-template-columns: clamp(100px, 16vw, 180px) 1fr clamp(50px, 6vw, 80px);
            align-items: center;
            gap: clamp(0.5rem, 1vw, 1rem);
        }

        .ch-label {
            font-family: var(--font-body);
            font-size: var(--small-size);
            font-weight: 600;
            color: var(--text-primary);
            text-align: right;
        }

        .ch-track {
            background: var(--border);
            border-radius: 3px;
            height: clamp(16px, 2.8vh, 36px);
            position: relative;
            overflow: hidden;
        }

        .ch-fill {
            height: 100%;
            border-radius: 3px;
            position: absolute;
            left: 0;
            top: 0;
            transition: width 1.0s var(--ease-out-expo);
            display: flex;
            align-items: center;
            padding-left: clamp(4px, 0.6vw, 8px);
        }

        .ch-fill-label {
            font-family: var(--font-display);
            font-size: var(--label-size);
            color: white;
            white-space: nowrap;
        }

        .ch-pct {
            font-family: var(--font-display);
            font-size: var(--body-size);
            color: var(--text-primary);
            font-weight: 900;
        }

        .ch-fill.complete { background: var(--data-green); }
        .ch-fill.high { background: #3d7a2c; }
        .ch-fill.medium { background: var(--data-amber); }
        .ch-fill.low { background: #cc4400; }

        .challenges-barriers {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: clamp(0.4rem, 1vw, 1rem);
            padding: 0 var(--slide-padding) clamp(0.5rem, 1.5vw, 1.5rem);
        }

        .barrier-block {
            background: white;
            border-top: 4px solid var(--accent);
            padding: clamp(0.4rem, 0.8vw, 0.8rem) clamp(0.6rem, 1.2vw, 1.2rem);
            border-radius: 0 0 4px 4px;
        }

        .barrier-title {
            font-family: var(--font-display);
            font-size: var(--small-size);
            color: var(--text-primary);
            margin-bottom: 3px;
        }

        .barrier-desc {
            font-family: var(--font-body);
            font-size: var(--small-size);
            color: var(--text-secondary);
            line-height: 1.4;
        }

        /* ===========================================
           SLIDE 8: TAKEAWAYS & CALL TO ACTION
           Dark background, numbered key findings
           =========================================== */
        .slide-takeaways { background: var(--bg-panel); }

        .takeaways-layout {
            display: grid;
            grid-template-rows: auto auto 1fr auto;
            height: 100%;
            overflow: hidden;
        }

        .findings-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: clamp(0.5rem, 1.2vw, 1.2rem);
            padding: 0 var(--slide-padding);
            align-content: center;
            overflow: hidden;
        }

        .finding-card {
            background: rgba(255,255,255,0.05);
            border: 1px solid rgba(255,255,255,0.08);
            border-radius: 6px;
            padding: clamp(0.5rem, 1.2vw, 1.2rem);
            display: grid;
            grid-template-columns: auto 1fr;
            gap: clamp(0.5rem, 1vw, 1rem);
            align-items: start;
        }

        .finding-num {
            font-family: var(--font-display);
            font-size: clamp(1.2rem, 3vw, 2.5rem);
            color: var(--accent-light);
            line-height: 1;
            opacity: 0.6;
        }

        .finding-text {
            font-family: var(--font-body);
            font-size: var(--small-size);
            color: rgba(255,255,255,0.75);
            line-height: 1.5;
        }

        .finding-text strong {
            color: rgba(255,255,255,0.95);
            display: block;
            font-size: var(--body-size);
            margin-bottom: 2px;
        }

        .cta-banner {
            margin: 0 var(--slide-padding);
            padding: clamp(0.6rem, 1.2vw, 1.2rem) clamp(1rem, 2vw, 2rem);
            background: var(--accent);
            border-radius: 6px;
            display: flex;
            justify-content: space-between;
            align-items: center;
            gap: 1rem;
            flex-shrink: 0;
            margin-bottom: clamp(0.5rem, 1.5vw, 1.5rem);
        }

        .cta-text {
            font-family: var(--font-display);
            font-size: var(--body-size);
            color: white;
            line-height: 1.3;
        }

        .cta-label {
            font-family: var(--font-body);
            font-size: var(--label-size);
            color: rgba(255,255,255,0.7);
            font-weight: 600;
            letter-spacing: 0.12em;
            text-transform: uppercase;
            white-space: nowrap;
        }

        /* ===========================================
           KEYBOARD HINT
           =========================================== */
        .keyboard-hint {
            position: fixed;
            bottom: clamp(0.75rem, 1.5vw, 1.5rem);
            left: 50%;
            transform: translateX(-50%);
            font-family: var(--font-body);
            font-size: var(--label-size);
            color: rgba(255,255,255,0.25);
            letter-spacing: 0.1em;
            z-index: 100;
            pointer-events: none;
            white-space: nowrap;
        }
    </style>
</head>
